def test_hello_world_stdout_capture():
    """Verify that hello_world.py prints 'hello world' to stdout."""
    # Capture stdout by running the script as a subprocess
    script_path = Path(__file__).parent / "hello_world.py"
    result = subprocess.run(
        [sys.executable, str(script_path)],
        capture_output=True,
        text=True,
        timeout=5
    )
    
    assert result.returncode == 0, f"Script exited with code {result.returncode}"
    assert result.stdout.strip() == "hello world", (
        f"Expected 'hello world', got '{result.stdout.strip()}'"
    )
    assert result.stderr == "", f"Unexpected stderr output: {result.stderr}"


