def test_hello_world_import_safety():
    """Verify importing the script doesn't cause side effects."""
    # Capture stdout before import
    old_stdout = sys.stdout
    sys.stdout = io.StringIO()
    
    try:
        # Import the script (it will execute on import)
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            "hello_world",
            Path(__file__).parent / "hello_world.py"
        )
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        
        output = sys.stdout.getvalue()
        assert "hello world" in output, (
            f"Expected 'hello world' in output, got: {output}"
        )
    finally:
        sys.stdout = old_stdout


