def test_hello_world_no_file_access():
    """Verify script doesn't access files outside its scope."""
    import tempfile
    
    script_path = Path(__file__).parent / "hello_world.py"
    
    # Create a temporary file to check if script accesses it
    with tempfile.NamedTemporaryFile(delete=False, suffix='.txt') as f:
        temp_path = f.name
        f.write(b"sensitive data")
    
    try:
        result = subprocess.run(
            [sys.executable, str(script_path)],
            capture_output=True,
            text=True,
            timeout=5
        )
        assert result.returncode == 0
        assert result.stdout.strip() == "hello world"
        
        # Verify temp file wasn't modified
        with open(temp_path, 'rb') as f:
            assert f.read() == b"sensitive data", "Script modified external file"
    finally:
        os.unlink(temp_path)


